referenceSolutions.javascript:
export function solve(initial, stages) {
  let result = initial;
  for (const stage of stages) {
    if (stage.op === "stop") return stage.value;
    result = stage.op === "add" ? result + stage.value : result * stage.value;
  }
  return result;
}

